function filtrarCobros() {
  const ft = document.getElementById('fc-tipo').value;
  const fp = document.getElementById('fc-plan').value;
  const fe = document.getElementById('fc-estado').value;
  const fb = document.getElementById('fc-buscar').value.toLowerCase();
  const rows = DETALLE_C.filter(a =>
    (!ft || a.tipo === ft) &&
    (!fp || a.plan === fp) &&
    (!fe || (fe==='si' ? a.pagado : !a.pagado)) &&
    (!fb || a.nombre.toLowerCase().includes(fb))
  );
  const tbody = document.getElementById('tbody-cobros');
  if(!tbody) return;
  tbody.innerHTML = rows.length ? rows.map(a => {
    const estadoBadge = a.bonificado
      ? '<span class="badge badge-grey">★ Bonificado</span>'
      : a.pagado
        ? '<span class="badge badge-green">✓ Pagó</span>'
        : '<span class="badge badge-red">✗ Sin pago</span>';
    const medio = a.pago ? a.pago.medio : '—';
    const rowBg = a.bonificado ? 'background:#F8F9FA' : a.pagado ? '' : 'background:#FFF5F5';
    const cuotaDisplay = a.bonificado ? '<span style="color:var(--muted);font-style:italic">Bonificado</span>' : fmtArs(a.cuota_est);
    return `<tr style="${rowBg}">
      <td>${a.nombre}</td>
      <td><span class="badge badge-blue">${a.plan}</span></td>
      <td style="font-size:11px">${a.delegacion}</td>
      <td style="font-size:11px">${a.tipo}</td>
      <td class="right">${cuotaDisplay}</td>
      <td>${estadoBadge}</td>
      <td class="right">${a.cobrado ? fmtArs(a.cobrado) : '—'}</td>
      <td style="font-size:11px;color:var(--muted)">${medio}</td>
    </tr>`;
  }).join('') : '<tr><td colspan="8" style="text-align:center;color:var(--muted);padding:20px">Sin resultados</td></tr>';
  document.getElementById('count-cobros').textContent = rows.length + ' afiliado' + (rows.length!==1?'s':'');
}

function renderCobrosTabla() {
  const tbody = document.getElementById('cobros-tabla-meses');
  if(!tbody || !COBROS_TABLA.length) return;
  tbody.innerHTML = COBROS_TABLA.map(m => {
    const difClass = m.diferencia >= 0 ? 'pos' : 'neg';
    return `<tr>
      <td><strong>${m.mes}</strong></td>
      <td class="right">${fmtArs(m.proyectado)}</td>
      <td class="right bold-val">${fmtArs(m.cobrado_bruto)}</td>
      <td class="right">${fmtArs(m.cobrado_neto)}</td>
      <td class="right ${difClass}">${fmtArs(m.diferencia)}</td>
      <td class="right">${m.pct}%</td>
      <td class="right">${m.count}</td>
    </tr>`;
  }).join('');
}

// ── padrón tab ────────────────────────────────────────────────────────────────
function filtrarPadron() {
  const ft = document.getElementById('pp-tipo').value;
  const fp = document.getElementById('pp-plan').value;
  const fr = document.getElementById('pp-rol').value;
  const fd = document.getElementById('pp-deleg').value;
  const fb = document.getElementById('pp-buscar').value.toLowerCase();
  const rows = PADRON_DATA.filter(a =>
    (!ft || a.tipo === ft) &&
    (!fp || a.plan === fp) &&
    (!fr || a.rol  === fr) &&
    (!fd || a.delegacion === fd) &&
    (!fb || a.nombre.toLowerCase().includes(fb))
  );
  const tbody = document.getElementById('tbody-padron');
  if(!tbody) return;
  tbody.innerHTML = rows.length ? rows.map(a => {
    const tipoBadge = a.tipo==='COMERCIAL'
      ? '<span class="badge badge-green">COMERCIAL</span>'
      : a.tipo==='PLAN EMPLEADO'
        ? '<span class="badge badge-yellow">PLAN EMP.</span>'
        : '<span class="badge badge-grey">HISTÓRICO</span>';
    const rolBadge = a.rol==='Adherente'
      ? '<span style="color:var(--muted);font-size:11px">Adherente</span>'
      : a.rol==='Plan Empleado'
        ? '<span style="color:#B8860B;font-size:11px">Plan Emp.</span>'
        : '<strong style="font-size:11px">Titular</strong>';
    const cuil_t = (a.cuil_titular && a.cuil_titular !== a.cuil)
      ? `<span style="font-size:11px;color:var(--muted)">${a.cuil_titular}</span>` : '—';
    return `<tr>
      <td>${a.nombre}</td>
      <td style="font-size:11px;font-variant-numeric:tabular-nums">${a.cuil||'—'}</td>
      <td><span class="badge badge-blue">${a.plan}</span></td>
      <td>${tipoBadge}</td><td>${rolBadge}</td>
      <td style="font-size:11px">${a.delegacion}</td>
      <td>${cuil_t}</td>
    </tr>`;
  }).join('') : '<tr><td colspan="7" style="text-align:center;color:var(--muted);padding:20px">Sin resultados</td></tr>';
  document.getElementById('count-padron').textContent = rows.length + ' afiliado' + (rows.length!==1?'s':'');
}

function initPadronKpis() {
  const kpiEl = document.getElementById('padron-kpis');
  if(!kpiEl) return;
  const hist = PADRON_DATA.filter(a=>a.tipo==='HISTORICO').length;
  const com  = PADRON_DATA.filter(a=>a.tipo==='COMERCIAL').length;
  const pe   = PADRON_DATA.filter(a=>a.tipo==='PLAN EMPLEADO').length;
  const tit  = PADRON_DATA.filter(a=>a.rol==='Titular').length;
  const adh  = PADRON_DATA.filter(a=>a.rol==='Adherente').length;
  const kpis = [
    ['Total Afiliados', PADRON_DATA.length, '', 'blue'],
    ['Titulares',  tit,  '', ''],
    ['Adherentes', adh,  '', 'cyan'],
    ['Histórico',  hist, 'OSPIF base', ''],
    ['COMERCIAL',  com,  'Ventas + GF', ''],
    ['Plan Empleado', pe, 'Bonificados', 'yellow'],
  ];
  kpiEl.innerHTML = kpis.map(([lbl,val,meta,cls])=>
    `<div class="kpi-card ${cls}">
      <div class="kpi-label">${lbl}</div>
      <div class="kpi-value">${val}</div>
      ${meta ? `<div class="kpi-meta">${meta}</div>` : ''}
    </div>`).join('');
}

// ── INFORME GENERAL: tabla combinada ─────────────────────────────────────────
function renderInformeGeneral() {
  const base = IG_ROWS;
  if(!base.length) return;

  // Leer inputs de proyección
  const v1 = parseInt(document.getElementById('proj-gs1-v')?.value||0)||0;
  const m1 = parseFloat(document.getElementById('proj-gs1-m')?.value||0)||0;
  const v2 = parseInt(document.getElementById('proj-gs2-v')?.value||0)||0;
  const m2 = parseFloat(document.getElementById('proj-gs2-m')?.value||0)||0;

  // Calcular datos efectivos: históricos igual, proyectados con acumulado
  let projCount = 0;
  const rows = base.map(r => {
    if(!r.proyectado) return r;
    projCount++;
    const pg1 = {
      ventas:  r.pg1.ventas  + v1 * projCount,
      capitas: r.pg1.capitas + v1 * projCount,
      cobrado: r.pg1.cobrado + v1 * projCount * m1,
    };
    const pg2 = {
      ventas:  r.pg2.ventas  + v2 * projCount,
      capitas: r.pg2.capitas + v2 * projCount,
      cobrado: r.pg2.cobrado + v2 * projCount * m2,
    };
    return {...r, pg1, pg2};
  });

  // Cabecera de meses
  let thead = '<tr><th style="min-width:180px">Concepto</th>';
  rows.forEach(r => {
    const bgH = r.proyectado ? 'background:rgba(242,183,5,.12)' : '';
    thead += `<th class="right" style="min-width:90px;${bgH}">${r.label}${r.proyectado?' <span style="color:var(--yellow);font-size:10px">*</span>':''}</th>`;
  });
  thead += '</tr>';
  document.getElementById('thead-ig').innerHTML = thead;

  function secRow(lab, bgC, col) {
    return `<tr><td colspan="${rows.length+1}" style="padding:6px 10px;background:${bgC};font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.8px;color:${col}">${lab}</td></tr>`;
  }
  function dataRow(lab, fn, fmt, bold, red) {
    const s = `${bold?'font-weight:700;':''}${red?'color:#E74C3C;':''}`;
    let h = `<tr><td style="${s}">${lab}</td>`;
    rows.forEach(r => {
      const bg = r.proyectado ? 'background:rgba(242,183,5,.06)' : '';
      h += `<td class="right" style="${s};${bg}">${fmt(fn(r))}</td>`;
    });
    return h + '</tr>';
  }

  let tbody = '';
  tbody += secRow('CÁPITAS','#f0f4fb','var(--muted)');
  tbody += dataRow('Superadores GS100', r=>r.sg1.capitas, fmtNum, false,false);
  tbody += dataRow('Superadores GS200', r=>r.sg2.capitas, fmtNum, false,false);
  tbody += dataRow('Prepagos GS100',    r=>r.pg1.capitas, fmtNum, false,false);
  tbody += dataRow('Prepagos GS200',    r=>r.pg2.capitas, fmtNum, false,false);
  tbody += dataRow('TOTAL CÁPITAS', r=>r.sg1.capitas+r.sg2.capitas+r.pg1.capitas+r.pg2.capitas, fmtNum, true,false);
  tbody += secRow('COBRADO / PROYECTADO','#fff5f5','#E74C3C');
  tbody += dataRow('Superadores GS100', r=>r.sg1.cobrado, fmtArs, false,true);
  tbody += dataRow('Superadores GS200', r=>r.sg2.cobrado, fmtArs, false,true);
  tbody += dataRow('Prepagos GS100',    r=>r.pg1.cobrado, fmtArs, false,true);
  tbody += dataRow('Prepagos GS200',    r=>r.pg2.cobrado, fmtArs, false,true);
  tbody += dataRow('TOTAL COBRADO', r=>r.sg1.cobrado+r.sg2.cobrado+r.pg1.cobrado+r.pg2.cobrado, fmtArs, true,true);

  document.getElementById('tbody-ig').innerHTML = tbody;
}

// ── INFORME SUPERADORES ───────────────────────────────────────────────────────
let supFiltro = 'activos';

function fmtSupMes(m) {
  if (!m || m.status === 'none') return '<span style="color:var(--muted)">—</span>';
  if (m.status === 'baja') return '<span style="color:var(--red);font-size:11px;font-weight:600">BAJA</span>';
  return '<span style="color:#43A047;font-variant-numeric:tabular-nums">' + fmtArs(m.amount) + '</span>';
}

function filtrarSup(filtro, btn) {
  supFiltro = filtro;
  document.querySelectorAll('#btn-sup-activos,#btn-sup-todos').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  renderSuperadores();
}

function renderSuperadores() {
  const data = supFiltro === 'activos' ? SUPERADORES.filter(s=>s.activo) : SUPERADORES;
  document.getElementById('sup-count').textContent = ' — ' + data.length + ' superador' + (data.length!==1?'es':'');
  const ABREV = ['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep'];
  document.getElementById('tbody-superadores').innerHTML = data.length === 0
    ? '<tr><td colspan="14" style="text-align:center;color:var(--muted);padding:20px">Sin resultados</td></tr>'
    : data.map(s => {
        const total = MESES_SUP_NAMES.reduce((acc,m) => acc + (s.meses[m]?.amount||0), 0);
        const mesCells = MESES_SUP_NAMES.map((m,i) => {
          const isSep = (i === 8);
          const cell = fmtSupMes(s.meses[m]);
          return `<td class="right"${isSep?' style="background:rgba(0,200,250,.06)"':''}>${cell}</td>`;
        }).join('');
        const planBadge = s.plan==='GS200'
          ? '<span class="badge badge-blue">GS200</span>'
          : '<span class="badge badge-grey">GS100</span>';
        const actBadge  = s.activo
          ? '<span class="badge badge-green" style="font-size:10px">Activo</span>'
          : '<span class="badge badge-red"   style="font-size:10px">Baja</span>';
        return `<tr>
          <td><strong>${s.nombre}</strong> ${actBadge}</td>
          <td>${planBadge}</td>
          <td class="right">${s.integ}</td>
          <td class="right">${fmtArs(s.base)}</td>
          ${mesCells}
          <td class="right bold-val">${fmtArs(total)}</td>
        </tr>`;
      }).join('');
}

// ── init ──────────────────────────────────────────────────────────────────────
renderInformeGeneral();
recalcInforme();
filtrarSeguimiento();
renderCostos();
filtrarCobros();
renderCobrosTabla();
initPadronKpis();
filtrarPadron();
renderSuperadores();
document.getElementById('period-bar-informe').style.display='none';
</script>
</body>
</html>
